:root{--bg:#14171c;--panel:#1b1f26;--alt:#20252d;--border:#2c323c;--text:#e6e8eb;--muted:#8b93a1;--accent:#e8a33d;--good:#4caf7d;--bad:#e5484d;--mono:Consolas,monospace;--sans:system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 var(--sans)}header{display:flex;justify-content:space-between;align-items:center;padding:14px 24px;background:var(--panel);border-bottom:1px solid var(--border)}h1{margin:0;font-size:15px}h1 span,.tab.active{color:var(--accent)}main{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--border);min-height:calc(100vh - 49px)}section{padding:24px;background:var(--bg)}h2{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}h3{font-size:13px;margin:14px 0 8px}.card{background:var(--panel);border:1px solid var(--border);padding:16px;border-radius:4px;margin-bottom:14px}label{display:block;color:var(--muted);font-size:12px;margin:10px 0 4px}input,select{width:100%;background:var(--alt);border:1px solid var(--border);color:var(--text);padding:7px 9px;border-radius:3px}.row{display:flex;gap:10px}.row>*{flex:1}button{cursor:pointer;font-family:var(--sans)}.primary{width:100%;margin-top:14px;padding:9px;border:0;border-radius:3px;background:var(--accent);color:#1a1200;font-weight:700}.secondary,.nav,.remove{background:var(--alt);color:var(--text);border:1px solid var(--border);padding:5px 10px;border-radius:3px}.link{border:0;background:none;color:var(--accent);text-decoration:underline}.tabs{display:flex;border-bottom:1px solid var(--border);margin-bottom:16px}.tab{padding:8px 14px;color:var(--muted);cursor:pointer;border-bottom:2px solid transparent}.tab.active{border-bottom-color:var(--accent)}.tab-panel{display:none}.tab-panel.active{display:block}.msg{padding:8px 10px;margin-top:10px;border-radius:3px;font:12px var(--mono)}.good{color:var(--good);background:#4caf7d20}.bad{color:var(--bad);background:#e5484d20}.hint{font-size:11px;color:var(--muted)}.validation{color:var(--bad);font-size:12px;margin-top:8px}.mono,.pill{font-family:var(--mono)}.pill{font-size:10px;padding:2px 7px;border-radius:10px;background:#4caf7d20;color:var(--good)}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid var(--border);text-align:left}td{font-family:var(--mono)}.cal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.cal-title{font:600 14px var(--mono)}.week,.grid{display:grid;grid-template-columns:repeat(7,1fr)}.week div{text-align:center;font-size:10px;color:var(--muted);padding:4px}.day{min-height:84px;background:var(--panel);border:1px solid var(--border);padding:6px}.day.empty{background:#1b1f2660}.day.has{cursor:pointer}.day.has:hover{border-color:var(--accent)}.num{font:11px var(--mono);color:var(--muted)}.today .num{color:var(--accent)}.count{display:inline-block;margin-top:8px;padding:1px 6px;border-radius:8px;background:#e8a33d20;color:var(--accent);font:10px var(--mono)}.event{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;margin-top:4px;padding:2px 4px;background:var(--alt);border:0;border-left:2px solid var(--accent);color:var(--text);font:10px var(--mono)}.detail dl{display:grid;grid-template-columns:auto 1fr;gap:5px 14px;font-size:12px}.detail dt{color:var(--muted)}.detail dd{margin:0;font-family:var(--mono)}.fixture{border:1px solid var(--border);padding:12px;margin:10px 0;border-radius:3px}.fixture-top{display:flex;justify-content:space-between;align-items:center}.fixture-top h3{margin:0}.roster{list-style:none;padding:0}.roster li{border-bottom:1px solid var(--border);padding:7px 0;font-size:12px}@media(max-width:860px){main{grid-template-columns:1fr}}
</style></head><body>
<header><h1>INTRAMURAL <span>SCHEDULER</span></h1><div id="session-info"><span id="session-text">Not signed in</span> <button class="link" id="logout-btn" hidden>sign out</button></div></header><main>
<section><h2>Public Schedule — Confirmed Matches</h2><div class="card"><div class="cal-head"><button class="nav" id="prev" aria-label="Previous month">←</button><div class="cal-title" id="cal-title"></div><button class="nav" id="next" aria-label="Next month">→</button></div><div class="week"><div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div></div><div id="calendar" class="grid"></div><div id="match-detail" class="detail"></div></div><p class="hint">Refreshes every 5s. Select a date or match for full details. No sign-in required.</p></section>
<section><div id="login-box"><h2>Organizer Sign In</h2><div class="card"><label>Email</label><input id="login-email" type="email" value="bball-rep@example.edu"><label>Password</label><input id="login-password" type="password" value="rep-pass"><button class="primary" onclick="login()">Sign in</button><div id="login-msg"></div></div></div>
<div id="organizer-box" hidden><div class="tabs"><div class="tab active" data-tab="book">Book Match</div><div class="tab" data-tab="roster">Roster</div><div class="tab" data-tab="generate">Generate</div><div class="tab" data-tab="drafts">Drafts</div></div>
<div class="tab-panel active" id="tab-book"><div class="card"><div class="row"><div><label>Home team</label><select id="b-home" class="teams"></select></div><div><label>Away team</label><select id="b-away" class="teams"></select></div></div><div class="row"><div><label>Venue</label><select id="b-venue" class="venues"></select></div><div><label>Sport</label><select id="b-sport" class="sports"></select></div></div><div class="row"><div><label>Start time</label><input id="b-start" type="datetime-local" step="60" value="2026-10-01T18:00"></div><div><label>End time</label><input id="b-end" type="datetime-local" step="60" value="2026-10-01T19:00"></div></div><label>Season</label><select id="b-season" class="seasons"></select><button class="primary" onclick="bookMatch()">Propose match</button><div id="book-msg"></div></div></div>
<div class="tab-panel" id="tab-roster"><div class="card"><label>Player name</label><input id="p-name" placeholder="Full name"><label>Roll number</label><input id="p-roll" placeholder="e.g. R101"><p class="hint">Letters/numbers and optional hyphens; 3–20 characters.</p><div class="row"><div><label>Team</label><select id="p-team" class="teams"></select></div><div><label>Sport</label><select id="p-sport" class="sports"></select></div></div><label>Season</label><select id="p-season" class="seasons"></select><div id="roster-validation" class="validation"></div><button class="primary" onclick="addPlayer()">Add to roster</button><div id="roster-msg"></div><h3>Current roster</h3><p id="roster-note" class="hint"></p><ul id="roster-list" class="roster"></ul></div></div>
<div class="tab-panel" id="tab-generate"><div class="card"><div class="row"><div><label>Sport</label><select id="g-sport" class="sports"></select></div><div><label>Season</label><select id="g-season" class="seasons"></select></div></div><h3>Candidate fixtures</h3><div id="fixtures"></div><button class="secondary" id="add-fixture" type="button">+ Add fixture</button><button class="primary" onclick="generateSchedule()">Generate (async)</button><div id="generate-msg"></div></div></div>
<div class="tab-panel" id="tab-drafts"><h3>Drafts awaiting publish</h3><table><thead><tr><th>ID</th><th>Ver</th><th></th></tr></thead><tbody id="drafts-body"></tbody></table><div id="publish-msg"></div></div></div></section></main>
<script>
const API_BASE="http://localhost:8000",refs={teams:[1,2,3,4],venues:[1,2],seasons:[1],sports:["Basketball","Football","Volleyball"]};let session={token:null,role:null,sportScope:null},drafts=[],matches=[],month=new Date(new Date().getFullYear(),new Date().getMonth(),1),selected=null;const rosters=new Map(),$=id=>document.getElementById(id),esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;"})[c]);
// Reference data is fetched from the public GET /teams, /venues, and /seasons endpoints.
function hdr(){return session.token?{Authorization:"Bearer "+session.token}:{}}async function api(path,opt={}){let r=await fetch(API_BASE+path,{...opt,headers:{"Content-Type":"application/json",...hdr(),...(opt.headers||{})}}),b=await r.json().catch(()=>({}));return{ok:r.ok,status:r.status,body:b}}function msg(id,text,ok){$(id).innerHTML=`<div class="msg ${ok?"good":"bad"}">${text}</div>`}function opts(a,chosen){return a.map((x,i)=>`<option value="${esc(x)}"${String(x)===String(chosen)?" selected":""}>${typeof x==="number"?"#"+x:esc(x)}</option>`).join("")}function fill(){document.querySelectorAll(".teams,.fh,.fa").forEach((e,i)=>e.innerHTML=opts(refs.teams,i%2?2:1));document.querySelectorAll(".venues,.fv").forEach(e=>e.innerHTML=opts(refs.venues,1));document.querySelectorAll(".seasons").forEach(e=>e.innerHTML=opts(refs.seasons,1));document.querySelectorAll(".sports").forEach(e=>e.innerHTML=opts(refs.sports,"Basketball"))}function iso(v){return v&&(v.length===16?v+":00":v)}function nice(v){let d=new Date(v);return Number.isNaN(d)?v:d.toLocaleString([],{dateStyle:"medium",timeStyle:"short"})}
function detail(m){$("match-detail").innerHTML=m?`<div class="card"><h3>Match details</h3><dl><dt>Sport</dt><dd>${esc(m.sport)}</dd><dt>Teams</dt><dd>Team ${esc(m.home_team_id)} vs Team ${esc(m.away_team_id)}</dd><dt>Venue</dt><dd>Venue ${esc(m.venue_id)}</dd><dt>Start</dt><dd>${esc(nice(m.start_time))}</dd><dt>End</dt><dd>${esc(nice(m.end_time))}</dd><dt>Status</dt><dd><span class="pill">${esc(m.status)}</span></dd></dl></div>`:""}
function calendar(){let y=month.getFullYear(),mo=month.getMonth(),by={};matches.forEach(m=>{let d=new Date(m.start_time);if(!Number.isNaN(d)&&d.getFullYear()===y&&d.getMonth()===mo)(by[d.getDate()]??=[]).push(m)});$("cal-title").textContent=month.toLocaleDateString([],{month:"long",year:"numeric"});let first=new Date(y,mo,1).getDay(),last=new Date(y,mo+1,0).getDate(),out="";for(let i=0;i<first;i++)out+='<div class="day empty"></div>';for(let n=1;n<=last;n++){let a=by[n]||[],now=new Date(),today=now.getFullYear()===y&&now.getMonth()===mo&&now.getDate()===n;out+=`<div class="day ${a.length?"has":""} ${today?"today":""}" ${a.length?`data-day="${n}" tabindex="0"`:""}><div class="num">${n}</div>${a.length?`<span class="count">${a.length} match${a.length>1?"es":""}</span>`:""}${a.slice(0,2).map(m=>`<button class="event" data-id="${esc(m.id)}">${esc(m.sport)} · ${esc(m.home_team_id)}–${esc(m.away_team_id)}</button>`).join("")}${a.length>2?`<div class="hint">+${a.length-2} more</div>`:""}</div>`}for(let i=first+last;i<42;i++)out+='<div class="day empty"></div>';$("calendar").innerHTML=out;document.querySelectorAll(".event").forEach(e=>e.onclick=x=>{x.stopPropagation();selected=matches.find(m=>String(m.id)===e.dataset.id);detail(selected)});document.querySelectorAll(".day.has").forEach(e=>{let open=()=>{selected=by[e.dataset.day][0];detail(selected)};e.onclick=x=>{if(!x.target.closest(".event"))open()};e.onkeydown=x=>{if(x.key==="Enter"||x.key===" "){x.preventDefault();open()}}})}async function loadPublicSchedule(){let r=await api("/schedules?season=active");matches=r.ok&&Array.isArray(r.body)?r.body:[];if(selected)selected=matches.find(m=>m.id===selected.id)||null;calendar();detail(selected)}$("prev").onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1);calendar()};$("next").onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1);calendar()};
async function login(){let r=await api("/auth/login",{method:"POST",body:JSON.stringify({email:$("login-email").value,password:$("login-password").value})});if(!r.ok)return msg("login-msg",esc(r.body.detail||"Login failed"),false);session={token:r.body.access_token,role:r.body.role,sportScope:r.body.sport_scope};$("login-box").hidden=true;$("organizer-box").hidden=false;$("logout-btn").hidden=false;$("session-text").innerHTML=`<b>${esc(session.role)}</b>${session.sportScope?" · "+esc(session.sportScope):" · global scope"}`}$("logout-btn").onclick=()=>{session={token:null,role:null,sportScope:null};drafts=[];renderDrafts();$("login-box").hidden=false;$("organizer-box").hidden=true;$("logout-btn").hidden=true;$("session-text").textContent="Not signed in"};document.querySelectorAll(".tab").forEach(t=>t.onclick=()=>{document.querySelectorAll(".tab,.tab-panel").forEach(x=>x.classList.remove("active"));t.classList.add("active");$("tab-"+t.dataset.tab).classList.add("active")});
async function bookMatch(){let p={home_team_id:+$("b-home").value,away_team_id:+$("b-away").value,venue_id:+$("b-venue").value,sport:$("b-sport").value,start_time:iso($("b-start").value),end_time:iso($("b-end").value),season_id:+$("b-season").value},r=await api("/schedules",{method:"POST",body:JSON.stringify(p)});if(!r.ok){let d=typeof r.body.detail==="object"?(r.body.detail.conflicts||[]).join("; "):r.body.detail;return msg("book-msg",`${r.status}: ${esc(d||"Could not create draft")}`,false)}msg("book-msg",`Draft created: match #${r.body.match_id} (version ${r.body.version})`,true);drafts.push({id:r.body.match_id,version:r.body.version});renderDrafts()}
function renderRoster(){let t=+$("p-team").value,a=rosters.get(t)||[];$("roster-note").textContent=a.length?`Players added this session to Team ${t}.`:`No players added this session to Team ${t}.`;$("roster-list").innerHTML=a.map(p=>`<li><b>${esc(p.name)}</b> <span class="mono">${esc(p.roll_number)}</span> · ${esc(p.sport)} · season ${p.season_id}</li>`).join("")}async function addPlayer(){let p={name:$("p-name").value.trim(),roll_number:$("p-roll").value.trim(),team_id:+$("p-team").value,sport:$("p-sport").value,season_id:+$("p-season").value},err=[];if(!p.name)err.push("Player name is required.");if(!p.roll_number)err.push("Roll number is required.");else if(!/^[A-Za-z0-9]+(?:-[A-Za-z0-9]+)*$/.test(p.roll_number)||p.roll_number.length<3||p.roll_number.length>20)err.push("Roll number must be 3–20 letters/numbers, with optional hyphens.");if(!p.team_id||!p.sport||!p.season_id)err.push("Choose a team, sport, and season.");$("roster-validation").textContent=err.join(" ");if(err.length)return;let r=await api("/players",{method:"POST",body:JSON.stringify(p)});if(!r.ok){let d=String(r.body.detail||""),specific=r.status===409?(d.toLowerCase().includes("already on a team")?`This roll number is already assigned to a team for ${p.sport} in this season.`:`This roll number conflicts with an existing roster entry: ${d}`):`${r.status}: ${d||"Could not add player"}`;return msg("roster-msg",esc(specific),false)}let a=rosters.get(p.team_id)||[];a.push(p);rosters.set(p.team_id,a);renderRoster();msg("roster-msg",`Added: player #${r.body.player_id} → team #${r.body.team_id}`,true);$("p-name").value=$("p-roll").value=""}
function fixture(i){return `<div class="fixture"><div class="fixture-top"><h3>Fixture ${i}</h3><button class="remove" type="button">Remove</button></div><div class="row"><div><label>Home team</label><select class="fh">${opts(refs.teams,1)}</select></div><div><label>Away team</label><select class="fa">${opts(refs.teams,2)}</select></div></div><div class="row"><div><label>Venue</label><select class="fv">${opts(refs.venues,1)}</select></div><div><label>Start time</label><input class="fs" type="datetime-local" step="60" value="2026-10-05T18:00"></div></div><label>End time</label><input class="fe" type="datetime-local" step="60" value="2026-10-05T19:00"></div></div>`}function addFixture(){$("fixtures").insertAdjacentHTML("beforeend",fixture($("fixtures").children.length+1));let r=$("fixtures").lastElementChild;r.querySelector(".remove").onclick=()=>{r.remove();document.querySelectorAll(".fixture h3").forEach((h,i)=>h.textContent=`Fixture ${i+1}`)}}async function generateSchedule(){let f=[...document.querySelectorAll(".fixture")].map(r=>({home_team_id:+r.querySelector(".fh").value,away_team_id:+r.querySelector(".fa").value,venue_id:+r.querySelector(".fv").value,start_time:iso(r.querySelector(".fs").value),end_time:iso(r.querySelector(".fe").value)}));if(!f.length||f.some(x=>!x.start_time||!x.end_time||x.home_team_id===x.away_team_id))return msg("generate-msg","Each fixture needs different teams and both date/time values.",false);let r=await api("/schedule-generations",{method:"POST",body:JSON.stringify({sport:$("g-sport").value,season_id:+$("g-season").value,fixtures:f})});if(!r.ok)return msg("generate-msg",`${r.status}: ${esc(r.body.detail||"Could not start generation")}`,false);msg("generate-msg",`Job #${r.body.job_id} queued — polling…`,true);pollJob(r.body.job_id)}async function pollJob(id){let r=await api(`/schedule-generations/${id}`),b=r.body;if(!b.status)return msg("generate-msg","Could not retrieve job status.",false);if(b.status==="QUEUED"||b.status==="RUNNING"){msg("generate-msg",`<span class="pill">${b.status}</span> job #${id}`,true);return setTimeout(()=>pollJob(id),700)}if(b.status==="COMPLETED"){let made=b.result?.created_draft_match_ids||[];made.forEach(id=>drafts.push({id,version:1}));renderDrafts();return msg("generate-msg",`Done — ${made.length} draft(s) created, ${(b.result?.skipped||[]).length} skipped. See Drafts tab.`,true)}msg("generate-msg",`Job failed: ${esc(JSON.stringify(b.result))}`,false)}
function renderDrafts(){$("drafts-body").innerHTML=drafts.length?drafts.map((d,i)=>`<tr><td>#${d.id}</td><td>v${d.version}</td><td><button class="secondary" onclick="publishDraft(${i})">Publish</button></td></tr>`).join(""):'<tr><td colspan="3" class="hint">No drafts yet — book a match or generate a schedule.</td></tr>'}async function publishDraft(i){let d=drafts[i],r=await api(`/schedules/${d.id}/publish`,{method:"POST",body:JSON.stringify({expected_version:d.version})});if(!r.ok){let x=typeof r.body.detail==="object"?(r.body.detail.conflicts||[]).join("; "):r.body.detail;return msg("publish-msg",`#${d.id} → ${r.status}: ${esc(x||"Could not publish")}`,false)}msg("publish-msg",`#${d.id} published (now v${r.body.version})`,true);drafts.splice(i,1);renderDrafts();loadPublicSchedule()}
/* Reference data is public; load it before rendering organizer dropdowns. */
opts=function(a,chosen){return a.map(x=>`<option value="${esc(x.id??x)}"${String(x.id??x)===String(chosen)?" selected":""}>${esc(x.name??x.sport??x)}</option>`).join("")};
async function loadRefs(){let [t,v,s]=await Promise.all([api("/teams"),api("/venues"),api("/seasons")]);if(t.ok)refs.teams=t.body;if(v.ok)refs.venues=v.body;if(s.ok){refs.seasons=s.body;refs.sports=[...new Set([...refs.sports,...s.body.map(x=>x.sport)])]}fill()}
function rosterMarkup(teamId, rows){$("roster-note").textContent=rows.length?`Current roster for Team ${teamId}.`:`No players on Team ${teamId}.`;$("roster-list").innerHTML=rows.map(p=>`<li><b>${esc(p.name)}</b> <span class="mono">${esc(p.roll_number)}</span> · ${esc(p.sport)} <button class="remove" onclick="removePlayer(${p.id},${teamId})">Remove</button></li>`).join("")}
async function loadRoster(){let teamId=+$("p-team").value;if(!teamId)return;let r=await api(`/teams/${teamId}/roster`);if(r.ok)rosterMarkup(teamId,r.body)}
async function removePlayer(playerId,teamId){let r=await api(`/players/${playerId}/teams/${teamId}`,{method:"DELETE"});if(!r.ok)return msg("roster-msg",esc(r.body.detail||"Could not remove player"),false);msg("roster-msg","Player removed from team.",true);loadRoster()}
async function createTeam(){let name=$("new-team-name").value.trim(),sport=$("new-team-sport").value,season_id=+$("new-team-season").value;if(!name||!sport||!season_id)return msg("team-msg","Team name, sport, and season are required.",false);let r=await api("/teams",{method:"POST",body:JSON.stringify({name,sport,season_id})});if(!r.ok)return msg("team-msg",`${r.status}: ${esc(r.body.detail||"Could not create team")}`,false);msg("team-msg",`Team #${r.body.team_id} created.`,true);$("new-team-name").value="";await loadRefs()}
async function addPlayer(){let p={name:$('p-name').value.trim(),roll_number:$('p-roll').value.trim(),team_id:+$('p-team').value,sport:$('p-sport').value,season_id:+$('p-season').value},err=[];if(!p.name)err.push('Player name is required.');if(!p.roll_number)err.push('Roll number is required.');else if(!/^[A-Za-z0-9]+(?:-[A-Za-z0-9]+)*$/.test(p.roll_number)||p.roll_number.length<3||p.roll_number.length>20)err.push('Roll number must be 3–20 letters/numbers, with optional hyphens.');if(!p.team_id||!p.sport||!p.season_id)err.push('Choose a team, sport, and season.');$('roster-validation').textContent=err.join(' ');if(err.length)return;let r=await api('/players',{method:'POST',body:JSON.stringify(p)});if(!r.ok){let d=String(r.body.detail||''),specific=r.status===409?(d.toLowerCase().includes('already on a team')?`This roll number is already assigned to a team for ${p.sport} in this season.`:`This roll number conflicts with an existing roster entry: ${d}`):`${r.status}: ${d||'Could not add player'}`;return msg('roster-msg',esc(specific),false)}msg('roster-msg',`Added: player #${r.body.player_id} → team #${r.body.team_id}`,true);$('p-name').value=$('p-roll').value='';loadRoster()}
function renderDrafts(){$('drafts-body').innerHTML=drafts.length?drafts.map((d,i)=>`<tr><td>#${d.id}</td><td>v${d.version}</td><td><button class="secondary" onclick="publishDraft(${i})">Publish</button> <button class="remove" onclick="cancelDraft(${i})">Cancel</button></td></tr>`).join(''):'<tr><td colspan="3" class="hint">No drafts yet — book a match or generate a schedule.</td></tr>'}
