<script>
const API_BASE = "http://localhost:8000";

// In-memory only — deliberately not persisted to localStorage.
let session = { token: null, role: null, sportScope: null };
let drafts = []; // [{id, version}]

function authHeaders() {
  return session.token ? { "Authorization": "Bearer " + session.token } : {};
}

async function api(path, options = {}) {
  const res = await fetch(API_BASE + path, {
    ...options,
    headers: { "Content-Type": "application/json", ...authHeaders(), ...(options.headers || {}) },
  });
  const body = await res.json().catch(() => ({}));
  return { ok: res.ok, status: res.status, body };
}

function showMsg(elId, text, ok) {
  document.getElementById(elId).innerHTML =
    `<div class="msg ${ok ? "good" : "bad"}">${text}</div>`;
}

// ---------- Auth ----------
async function login() {
  const email = document.getElementById("login-email").value;
  const password = document.getElementById("login-password").value;
  const { ok, body } = await api("/auth/login", { method: "POST", body: JSON.stringify({ email, password }) });
  if (!ok) { showMsg("login-msg", body.detail || "Login failed", false); return; }

  session = { token: body.access_token, role: body.role, sportScope: body.sport_scope };
  document.getElementById("login-box").style.display = "none";
  document.getElementById("organizer-box").style.display = "block";
  document.getElementById("logout-btn").style.display = "inline";
  document.getElementById("session-text").innerHTML =
    `<b>${session.role}</b>${session.sportScope ? " &middot; " + session.sportScope : " &middot; global scope"}`;
}

function logout() {
  session = { token: null, role: null, sportScope: null };
  drafts = [];
  renderDrafts();
  document.getElementById("login-box").style.display = "block";
  document.getElementById("organizer-box").style.display = "none";
  document.getElementById("logout-btn").style.display = "none";
  document.getElementById("session-text").textContent = "Not signed in";
}
document.getElementById("logout-btn").onclick = logout;

// ---------- Tabs ----------
document.querySelectorAll(".tab").forEach(tab => {
  tab.onclick = () => {
    document.querySelectorAll(".tab").forEach(t => t.classList.remove("active"));
    document.querySelectorAll(".tab-panel").forEach(p => p.classList.remove("active"));
    tab.classList.add("active");
    document.getElementById("tab-" + tab.dataset.tab).classList.add("active");
  };
});

// ---------- Public schedule (no auth) ----------
async function loadPublicSchedule() {
  const { ok, body } = await api("/schedules?season=active");
  const tbody = document.getElementById("public-schedule-body");
  if (!ok || !body.length) {
    tbody.innerHTML = `<tr class="empty-row"><td colspan="5">No confirmed matches yet.</td></tr>`;
    return;
  }
  tbody.innerHTML = body.map(m => `
    <tr>
      <td>${m.id}</td>
      <td>${m.sport}</td>
      <td>Team ${m.home_team_id} vs Team ${m.away_team_id}</td>
      <td>Venue ${m.venue_id}</td>
      <td>${m.start_time}</td>
    </tr>`).join("");
}
loadPublicSchedule();
setInterval(loadPublicSchedule, 5000);

// ---------- Book a match ----------
async function bookMatch() {
  const payload = {
    home_team_id: Number(document.getElementById("b-home").value),
    away_team_id: Number(document.getElementById("b-away").value),
    venue_id: Number(document.getElementById("b-venue").value),
    sport: document.getElementById("b-sport").value,
    start_time: document.getElementById("b-start").value,
    end_time: document.getElementById("b-end").value,
    season_id: Number(document.getElementById("b-season").value),
  };
  const { ok, status, body } = await api("/schedules", { method: "POST", body: JSON.stringify(payload) });
  if (!ok) {
    const detail = typeof body.detail === "object" ? JSON.stringify(body.detail.conflicts) : body.detail;
    showMsg("book-msg", `${status}: ${detail}`, false);
    return;
  }
  showMsg("book-msg", `Draft created: match #${body.match_id} (version ${body.version})`, true);
  drafts.push({ id: body.match_id, version: body.version });
  renderDrafts();
}

// ---------- Roster ----------
async function addPlayer() {
  const payload = {
    name: document.getElementById("p-name").value,
    roll_number: document.getElementById("p-roll").value,
    team_id: Number(document.getElementById("p-team").value),
    sport: document.getElementById("p-sport").value,
    season_id: Number(document.getElementById("p-season").value),
  };
  const { ok, status, body } = await api("/players", { method: "POST", body: JSON.stringify(payload) });
  showMsg("roster-msg", ok ? `Added: player #${body.player_id} → team #${body.team_id}` : `${status}: ${body.detail}`, ok);
}

// ---------- Async generation ----------
async function generateSchedule() {
  let fixtures;
  try { fixtures = JSON.parse(document.getElementById("g-fixtures").value); }
  catch (e) { showMsg("generate-msg", "Invalid JSON in fixtures", false); return; }

  const payload = {
    sport: document.getElementById("g-sport").value,
    season_id: Number(document.getElementById("g-season").value),
    fixtures,
  };
  const { ok, status, body } = await api("/schedule-generations", { method: "POST", body: JSON.stringify(payload) });
  if (!ok) { showMsg("generate-msg", `${status}: ${body.detail}`, false); return; }

  showMsg("generate-msg", `Job #${body.job_id} queued — polling…`, true);
  pollJob(body.job_id);
}

async function pollJob(jobId) {
  const { body } = await api(`/schedule-generations/${jobId}`);
  showMsg("generate-msg",
    `<span class="status-pill ${body.status}">${body.status}</span> job #${jobId}`, true);

  if (body.status === "QUEUED" || body.status === "RUNNING") {
    setTimeout(() => pollJob(jobId), 700);
    return;
  }
  if (body.status === "COMPLETED") {
    const created = body.result.created_draft_match_ids || [];
    created.forEach(id => drafts.push({ id, version: 1 }));
    renderDrafts();
    showMsg("generate-msg",
