// ---------- Drafts / publish ----------
function renderDrafts() {
  const tbody = document.getElementById("drafts-body");
  if (!drafts.length) {
    tbody.innerHTML = `<tr class="empty-row"><td colspan="3">No drafts yet — book a match or generate a schedule.</td></tr>`;
    return;
  }
  tbody.innerHTML = drafts.map((d, i) => `
    <tr>
      <td>#${d.id}</td>
      <td>v${d.version}</td>
      <td><button class="secondary" onclick="publishDraft(${i})">Publish</button></td>
    </tr>`).join("");
}

async function publishDraft(index) {
  const d = drafts[index];
  const { ok, status, body } = await api(`/schedules/${d.id}/publish`, {
    method: "POST", body: JSON.stringify({ expected_version: d.version }),
